/* === 全局 border-box（现代项目推荐） === */
*, *::before, *::after {
  box-sizing: border-box;
}

/* === content-box vs border-box 宽度对比 === */
.standard {
  box-sizing: content-box;
  width: 200px;
  padding: 20px;
  border: 5px solid;
  /* 实际占宽 = 200 + 20×2 + 5×2 = 250px */
}

.weird {
  box-sizing: border-box;
  width: 200px;
  padding: 20px;
  border: 5px solid;
  /* 实际占宽 = 200px；内容区 = 200 - 40 - 10 = 150px */
}

/* === BFC 场景1：解决父子 margin 塌陷 === */
/* 子元素 margin-top: 20px 会穿透父元素 */
.parent-bfc {
  display: flow-root; /* 创建 BFC，阻止 margin 合并 */
}
.parent-bfc .child {
  margin-top: 20px; /* 被包含在 parent 内部，不会穿透 */
}

/* === BFC 场景2：解决浮动高度塌陷 === */
.clearfix-bfc {
  display: flow-root; /* 计算高度时包含浮动子元素 */
}
.clearfix-bfc .float-child {
  float: left;
  width: 200px;
  height: 100px;
}

/* 传统 clearfix（兼容 IE8 等老浏览器） */
.clearfix-old::after {
  content: '';
  display: table;  /* display:block 也可以，table 更稳妥 */
  clear: both;
}

/* === BFC 场景3：自适应两栏布局 === */
.sidebar {
  float: left;
  width: 200px;
}
.main-bfc {
  overflow: hidden; /* BFC 不与浮动重叠，宽度自适应 */
  /* 也可用 display: flow-root */
}

/* === 层叠上下文 === */
.stack-parent {
  position: relative;
  z-index: 1; /* 创建层叠上下文 */
}
.stack-parent .child {
  position: relative;
  z-index: 9999; /* 不会盖过 z-index: 2 的兄弟父元素的子元素 */
}

/* 层叠顺序（从底到顶）：
   1. 层叠上下文背景和边框
   2. z-index 负值定位元素
   3. 块级盒子
   4. 浮动盒子
   5. 行内盒子
   6. z-index: 0/auto 定位元素
   7. z-index 正值定位元素
*/
